from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any


TASK_DIR = Path(__file__).resolve().parent
SOURCE_DIR = TASK_DIR / "source"
CASE_FILE = TASK_DIR / "fixtures" / "molecular_panel.json"
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, Any], exit_code: int) -> int:
    REPORT_FILE.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_FILE.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def load_panel() -> list[dict[str, str]]:
    payload = json.loads(CASE_FILE.read_text(encoding="utf-8"))
    panel = payload["panel"]
    if not isinstance(panel, list) or not panel:
        raise ValueError("fixture panel must be a non-empty list")
    normalized: list[dict[str, str]] = []
    for index, case in enumerate(panel):
        if not isinstance(case, dict):
            raise ValueError(f"fixture case {index} is not an object")
        case_id = case.get("case_id")
        smiles = case.get("smiles")
        if not isinstance(case_id, str) or not case_id:
            raise ValueError(f"fixture case {index} has no case_id")
        if not isinstance(smiles, str) or not smiles:
            raise ValueError(f"fixture case {case_id} has no SMILES")
        normalized.append({"case_id": case_id, "smiles": smiles})
    return normalized


def main() -> int:
    try:
        panel = load_panel()
        sys.path.insert(0, str(SOURCE_DIR))
        import selfies as sf
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    observations: list[dict[str, Any]] = []
    failures: list[dict[str, str]] = []
    try:
        encoder_error = sf.EncoderError
        for case in panel:
            case_id = case["case_id"]
            smiles = case["smiles"]
            try:
                encoded = sf.encoder(smiles)
                tokens = list(sf.split_selfies(encoded))
                decoded = sf.decoder(encoded)
            except encoder_error as exc:
                failures.append(
                    {
                        "case_id": case_id,
                        "error_type": type(exc).__name__,
                        "stage": "translation",
                    }
                )
                continue

            if not encoded or not tokens or not decoded:
                failures.append(
                    {
                        "case_id": case_id,
                        "error_type": "EmptyTranslation",
                        "message": "encoder/decoder returned an empty molecular string",
                    }
                )
                continue

            observations.append(
                {
                    "case_id": case_id,
                    "input_smiles_length": len(smiles),
                    "selfies_tokens": len(tokens),
                    "decoded_smiles": decoded,
                }
            )
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )
    finally:
        if sys.path and sys.path[0] == str(SOURCE_DIR):
            sys.path.pop(0)

    success = not failures and len(observations) == len(panel)
    return write_report(
        {
            "schema_version": "1.0",
            "status": "post_fix_success" if success else "pre_fix_expected_failure",
            "observation": {
                "panel_size": len(panel),
                "completed_cases": len(observations),
                "failed_cases": failures,
                "successful_translations": observations,
            },
        },
        0 if success else 1,
    )


if __name__ == "__main__":
    raise SystemExit(main())

