        if a > b:
            a, b = b, a
        return (a, b) in self._bond_dict

    def has_out_ring_bond(self, src: int) -> bool:
        return self._ring_bond_flags[src]

    def get_attribution(
        self,
        o: Union[DirectedBond, Atom]
    ) -> List[Attribution]:
